var ids=['signin','home','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];var all=[];doc.pages.filter(p=>/^Proto iOS (Light|Dark)$/.test(p.name)).forEach(function(p){p.layers.filter(l=>l.name.indexOf('Screen/ios/')===0&&ids.indexOf(l.name.split('/').pop())>=0).forEach(function(s){var issues=[],links=[],symbols=0;function walk(l){if(/^link:/.test(l.name))links.push(l.name);if(/^sf:/.test(l.name))symbols++;(l.layers||[]).forEach(function(c){if(c.frame.x < -1||c.frame.y < -1||c.frame.x+c.frame.width>l.frame.width+1||c.frame.y+c.frame.height>l.frame.height+1)issues.push(l.name+'/'+c.name);walk(c);});}walk(s);var a={name:s.name,id:String(s.id),w:s.frame.width,h:s.frame.height,x:s.frame.x,y:s.frame.y,issues:issues,links:links,symbols:symbols};all.push(a);console.log(JSON.stringify(a));});});console.log(JSON.stringify({total:all.length,unique:new Set(all.map(a=>a.name)).size,overflow:all.reduce((n,a)=>n+a.issues.length,0),badLinks:all.flatMap(a=>a.links).filter(n=>/ \d+$/.test(n)).length}));